class ID3_CPP_EXPORT ID3_Tag
{
  ID3_TagImpl* _impl;
public:

  class Iterator
  {
  public:
    virtual ID3_Frame*       GetNext()       = 0;
    virtual ~Iterator() {};
  };

  class ConstIterator
  {
  public:
    virtual const ID3_Frame* GetNext()       = 0;
    virtual ~ConstIterator() {};
  };

public:

  ID3_Tag(const char *name = NULL, flags_t = (flags_t) ID3TT_ALL);
  ID3_Tag(const ID3_Tag &tag);
  virtual ~ID3_Tag();

