207: size_t RenderV2ToFile(const ID3_TagImpl& tag, fstream& file)
208: {
209:   ID3_Err err = ID3E_NoError;
210: 
211:   ID3D_NOTICE( "RenderV2ToFile: starting" );
212:   if (!file)
213:   {
214:     ID3D_WARNING( "RenderV2ToFile: error in file" );
215:     return 0;
216:   }
217: 
218:   String tagString;
219:   io::StringWriter writer(tagString);
220:   err = id3::v2::render(writer, tag);
221:   if (err != ID3E_NoError)
222:   {
223:     return (size_t)err; //impossible size, will make caller be able to set _last_error
224:   }
225: 
226:   ID3D_NOTICE( "RenderV2ToFile: rendered v2" );
227: 
228:   const char* tagData = tagString.data();
229:   size_t tagSize = tagString.size();
230:   // if the new tag fits perfectly within the old and the old one
231:   // actually existed (ie this isn't the first tag this file has had)
232:   if ((!tag.GetPrependedBytes() && !ID3_GetDataSize(tag)) ||
233:       (tagSize == tag.GetPrependedBytes()))
234:   {
235:     file.seekp(0, ios::beg);
236:     file.write(tagData, tagSize);
237:   }
238:   else
239:   {
240:     String filename = tag.GetFileName();
241:     String sTmpSuffix = ".XXXXXX";
242:     if (filename.size() + sTmpSuffix.size() > ID3_PATH_LENGTH)
243:     {
244:       // log this
245:       return (size_t)ID3E_NoFile;
246:       //ID3_THROW_DESC(ID3E_NoFile, "filename too long");
247:     }
248:     char sTempFile[ID3_PATH_LENGTH];
249:     strcpy(sTempFile, filename.c_str());
250:     strcat(sTempFile, sTmpSuffix.c_str());
251: 
252: #if ((defined(__GNUC__) && __GNUC__ >= 3  ) || !defined(HAVE_MKSTEMP))
253:     // This section is for Windows folk && gcc 3.x folk
254:     fstream tmpOut;
255:     err = createFile(sTempFile, tmpOut);
256:     if (err != ID3E_NoError)
257:     {
258:       tmpOut.close();
259:       remove(sTempFile);
260:       return (size_t)err; //impossible size, will make caller be able to set _last_error
261:     }
262: 
263:     tmpOut.write(tagData, tagSize);
264:     file.seekg(tag.GetPrependedBytes(), ios::beg);
265:     char *tmpBuffer[BUFSIZ];
